import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Suspense } from "react";
import { db } from "@/lib/db";
import { requireUser, isAdmin } from "@/lib/auth";
import { formatINR, gstIncluded } from "@/lib/money";
import { SITE } from "@/lib/site";
import { formatDate } from "@/lib/utils";
import { PrintButton } from "@/components/PrintButton";
import { paymentLabel } from "@/components/PaymentBadge";

export const metadata: Metadata = { title: "Tax Invoice", robots: { index: false } };

async function Invoice({ params }: { params: Promise<{ orderNumber: string }> }) {
  const { orderNumber } = await params;
  const user = await requireUser(`/order/${orderNumber}/invoice`);
  const order = await db.order.findUnique({ where: { orderNumber }, include: { items: true } });
  if (!order || !order.paidAt || (order.userId !== user.id && !isAdmin(user))) notFound();
  const addr = order.shippingAddress as Record<string, string>;
  const intraState = addr.state === SITE.address.state;
  const ratio = order.subtotal ? (order.subtotal - order.discount) / order.subtotal : 1;

  const rows = order.items.map((it) => {
    const gross = Math.round(it.unitPrice * it.quantity * ratio);
    const tax = gstIncluded(gross, it.gstRate);
    return { ...it, gross, tax, taxable: gross - tax };
  });
  const taxable = rows.reduce((s, r) => s + r.taxable, 0);
  const tax = rows.reduce((s, r) => s + r.tax, 0);

  return (
    <div className="mx-auto max-w-4xl bg-white p-8 text-sm print:p-0">
      <div className="mb-6 flex items-start justify-between border-b border-ink pb-4">
        <div>
          <p className="font-display text-2xl font-bold">{SITE.name.toUpperCase()}</p>
          <p>{SITE.address.line1}, {SITE.address.city},<br />{SITE.address.district}, {SITE.address.state} – {SITE.address.pincode}</p>
          <p>GSTIN: <span className="font-semibold">{SITE.gstin}</span> · {SITE.phone} · {SITE.email}</p>
        </div>
        <div className="text-right">
          <p className="text-lg font-bold">TAX INVOICE</p>
          <p>Invoice No: {order.invoiceNumber ?? `INV-${order.orderNumber}`}</p>
          <p>Date: {formatDate(order.paidAt)}</p>
          <p>Order: #{order.orderNumber}</p>
        </div>
      </div>
      <div className="mb-6 grid grid-cols-2 gap-6">
        <div>
          <p className="font-semibold">Bill / Ship to</p>
          <p>{addr.name}<br />{addr.line1}{addr.line2 && `, ${addr.line2}`}<br />{addr.city}, {addr.state} – {addr.pincode}<br />Ph: {addr.phone}</p>
        </div>
        <div className="text-right">
          <p>Place of supply: <span className="font-semibold">{addr.state}</span></p>
          <p>Payment: {paymentLabel(order.paymentMethod)} (Razorpay {order.razorpayPaymentId})</p>
        </div>
      </div>
      <table className="w-full border-collapse">
        <thead>
          <tr className="border-y border-ink text-left">
            <th className="py-2">#</th><th>Item</th><th>HSN/SKU</th><th className="text-right">Qty</th><th className="text-right">Taxable value</th>
            {intraState ? <><th className="text-right">CGST</th><th className="text-right">SGST</th></> : <th className="text-right">IGST</th>}
            <th className="text-right">Total</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={r.id} className="border-b border-line align-top">
              <td className="py-2">{i + 1}</td>
              <td>{r.name}{r.engravingText && <span className="block text-xs">Engraving: {r.engravingText}</span>}</td>
              <td>{r.sku}</td>
              <td className="text-right">{r.quantity}</td>
              <td className="text-right">{formatINR(r.taxable, true)}</td>
              {intraState ? (
                <><td className="text-right">{formatINR(r.tax / 2, true)}<span className="block text-xs">@{r.gstRate / 2}%</span></td><td className="text-right">{formatINR(r.tax / 2, true)}<span className="block text-xs">@{r.gstRate / 2}%</span></td></>
              ) : (
                <td className="text-right">{formatINR(r.tax, true)}<span className="block text-xs">@{r.gstRate}%</span></td>
              )}
              <td className="text-right">{formatINR(r.gross, true)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <div className="ml-auto mt-4 w-72 space-y-1">
        <div className="flex justify-between"><span>Taxable value</span><span>{formatINR(taxable, true)}</span></div>
        <div className="flex justify-between"><span>Total GST</span><span>{formatINR(tax, true)}</span></div>
        <div className="flex justify-between"><span>Shipping</span><span>{formatINR(order.shippingFee, true)}</span></div>
        <div className="flex justify-between border-t border-ink pt-1 text-base font-bold"><span>Grand total</span><span>{formatINR(order.total, true)}</span></div>
      </div>
      <p className="mt-10 text-xs text-muted">This is a computer-generated invoice and does not require a signature.</p>
      <div className="mt-6 print:hidden"><PrintButton /></div>
    </div>
  );
}

export default function InvoicePage({ params }: PageProps<"/order/[orderNumber]/invoice">) {
  return (
    <div className="py-6">
      <Suspense fallback={<div className="skeleton mx-auto h-96 max-w-4xl rounded-xl" />}>
        <Invoice params={params} />
      </Suspense>
    </div>
  );
}
